function chargerAvecThen() {
  // fetch retourne une Promise de Response.
  return fetch("/api/livres")
    // json() lit le corps puis retourne une nouvelle Promise.
    .then((reponse) => reponse.json())
    // Le résultat final est le nombre de livres.
    .then((livres) => livres.length);
}

async function chargerAvecAwait() {
  // await rend la succession plus proche d’une lecture ligne par ligne.
  const reponse = await fetch("/api/livres");
  const livres = await reponse.json();
  return livres.length;
}
